/* @lc app=leetcode id=1625 lang=kotlin */ class Solution { fun findLexSmallestString(s: String, a: Int, b: Int): String = HashSet<String>().also { it.add(s) }.let { seen -> generateSequence(listOf(s)) { f -> f.flatMap { t -> listOf(t.mapIndexed { i, c -> if (i % 2 == 1) '0' + (c - '0' + a) % 10 else c }.joinToString(""), t.takeLast(b) + t.dropLast(b)) }.filter { seen.add(it) }.takeIf { it.isNotEmpty() } }.flatten().min() } }